cmds:
{{- range $name, $job := .Values.cronjobs }}
---
apiVersion: batch/v1
kind: CronJob
metadata:
  name: {{ include "app.fullname" $ }}-{{ $name }}
spec:
  schedule: {{ $job.schedule | quote }}
{{- end }}

{{- if and .Values.autoscaling.enabled .Values.replicaCount }}
{{- fail "set either autoscaling.enabled or replicaCount, not both" }}
{{- end }}

{{- define "app.labels" -}}
{{- $base := dict "app.kubernetes.io/name" .Chart.Name "app.kubernetes.io/instance" .Release.Name -}}
{{- merge $base (.Values.extraLabels | default dict) | toYaml -}}
{{- end }}

{{- define "app.image" -}}
{{- $r := printf "%s%s" (default "" .Values.global.imageRegistry) .Values.image.repository -}}
{{- if .Values.image.digest }}{{ $r }}@{{ .Values.image.digest }}{{ else }}{{ $r }}:{{ .Values.image.tag | default .Chart.AppVersion }}{{ end -}}
{{- end }}

{{- if .Values.httpRoute.enabled }}
apiVersion: gateway.networking.k8s.io/v1
kind: HTTPRoute
spec:
  parentRefs: {{- toYaml .Values.httpRoute.parentRefs | nindent 4 }}
  hostnames: {{- toYaml .Values.httpRoute.hostnames | nindent 4 }}
{{- end }}

apiVersion: policy/v1
kind: PodDisruptionBudget
spec:
  maxUnavailable: {{ .Values.pdb.maxUnavailable }}
  selector:
    matchLabels: {{- include "app.selectorLabels" . | nindent 6 }}
